export const MAX_STEPS=100000;
export function cleanSteps(value){if(/^\s*-/.test(String(value)))return 0;return Math.max(0,Math.min(MAX_STEPS,Number(String(value).replace(/[^0-9]/g,''))||0));}
export function localISO(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
export function dateFor(start,index){const [y,m,d]=start.split('-').map(Number);return new Date(y,m-1,d+index,12);}
export function dayIndex(start,now=new Date()){const d=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12);return Math.round((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())-Date.UTC(...start.split('-').map((v,i)=>i===1?+v-1:+v)))/86400000);}
export function validISO(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=dateFor(s,0);return !Number.isNaN(+d)&&localISO(d)===s;}
export function initialState(){return {version:1,start:localISO(),goal:10000,addons:['stretch','breakfast'],days:Array.from({length:30},()=>({steps:null,lit:false,extras:{}})),secret:false,device:{}};}
// Legacy lit days earned a full glow; their old reference was not stored.
function legacyEntryGoal(state,day){return day.lit?Math.min(state.goal,Math.max(1,cleanSteps(day.steps))):state.goal;}
export function normalize(raw){const base=initialState();if(!raw||raw.version!==1)return base;base.start=validISO(raw.start)?raw.start:base.start;base.goal=Math.max(1,cleanSteps(raw.goal)||10000);base.addons=Array.isArray(raw.addons)?raw.addons.filter(x=>['stretch','breakfast'].includes(x)):base.addons;base.secret=raw.secret===true;base.roomOpened=raw.roomOpened===true;base.tapMode=raw.tapMode===true;base.sound=raw.sound===true;base.fireMuted=raw.fireMuted===true;for(let i=0;i<30;i++){const d=raw.days?.[i];if(d){base.days[i]={steps:d.steps==null?null:cleanSteps(d.steps),lit:d.lit===true,goalAtEntry:d.steps!=null||d.lit?Math.max(1,cleanSteps(d.goalAtEntry)||legacyEntryGoal(base,d)):null,order:Math.max(0,Math.min(30,Number(d.order)||0)),extras:{stretch:d.extras?.stretch===true,breakfast:d.extras?.breakfast===true}};}}if(raw.device&&typeof raw.device==='object'){for(let i=0;i<30;i++)if(raw.device[i]!=null)base.device[i]=cleanSteps(raw.device[i]);}let rank=0;for(const d of base.days){if(d.lit){rank++;if(!d.order)d.order=rank;}}return base;}
export function totals(state){const steps=state.days.reduce((s,d)=>s+(d.steps||0),0),goal=state.goal*30;return {steps,goal,remaining:Math.max(0,goal-steps),extra:Math.max(0,steps-goal),lit:state.days.filter(d=>d.lit).length};}
export function entryGoal(state,day){return day.goalAtEntry||state.goal;}
export function entryGlow(state,day){return Math.min(1,(day.steps||0)/entryGoal(state,day));}
export function recordDay(state,index,steps,mark=false){const d=state.days[index],wasLit=d.lit;d.goalAtEntry??=state.goal;d.steps=cleanSteps(steps);if(mark&&!wasLit){d.order=Math.min(30,totals(state).lit+1);d.lit=true;}return !wasLit&&d.lit;}
export function qualifySecret(deviceSteps){return cleanSteps(deviceSteps)>=20000;}

// Reviewed with Sofia: each marked day reveals the next discovery.
export const JOURNEY=[["The garden is waiting", 50, 60, "quiet"], ["A lantern near the cottage", 64, 50.1, "lamp"], ["A light beyond the flowers", 54.3, 59.7, "lamp"], ["The cottage path is lit", 56.5, 50.4, "lamp"], ["Fireflies in the garden", 43, 53, "fireflies"], ["Stars over the hills", 31, 16, "stars"], ["A robin on the oak branch", 35, 13, "bird"], ["A light in the oak", 94.5, 56.9, "window"], ["The cottage welcomes you", 54.3, 43.2, "window"], ["An upstairs window glows", 62.5, 37.4, "window"], ["Warmth behind the glass", 62.6, 42.9, "window"], ["The fox arrives", 25, 67, "fox"], ["Light on the water", 19, 38, "reflection"], ["The nearest lantern glows", 68.7, 84, "lamp"], ["Smoke curls from the chimney", 68.8, 24, "smoke"], ["The little oak window glows", 90.4, 56.5, "window"], ["Red leaves from the oak", 45, 27, "leaves"], ["An owl above the fox’s door", 90.5, 44, "owl"], ["A hedgehog by the lantern", 65.2, 77, "hedgehog"], ["Every cottage window is warm", 70.2, 40, "window"], ["Two owlets beside the owl", 90.5, 45.4, "owlets"], ["A brighter evening sky", 24, 18, "stars"], ["A shooting star", 42, 18, "shooting"], ["Pumpkins by the cottage", 52.3, 48.7, "pumpkins"], ["Ripples on the water", 20, 39, "ripples"], ["The fox curls up to sleep", 25, 72, "fox"], ["A snail by the lantern", 67.2, 90.4, "snail"], ["More sky through the leaves", 48, 20, "canopy"], ["Baby snails by the lantern", 69, 90, "baby-snails"], ["A light in the attic", 82, 72, "fox"], ["Your garden, alive", 52, 68, "finale"]];
export function sceneFor(stage){const n=Math.max(0,Math.min(30,Math.floor(+stage)||0));return {stage:n,label:JOURNEY[n][0],x:JOURNEY[n][1],y:JOURNEY[n][2],kind:JOURNEY[n][3],pathLights:[1,2,3].filter(s=>n>=s).length,fox:n>=11,smoke:n>=14,leaves:n>=16,stars:n>=5,shooting:n>=22,reflection:n>=12,floating:0,finale:n===30};}
